  ('translation', 'services.visas.pages.EB2NIW.intro', 'en', '"EB2-NIW is for qualified professionals who wish to immigrate to the US based on their professional merit without a direct job offer, by demonstrating substantial benefit to the US national interest."'::jsonb, 'published', 'json_seed'),
