  ('translation', 'services.visas.pages.EB2NIW.intro', 'es', '"EB2-NIW es para profesionales calificados que desean inmigrar a EE. UU. por su mérito profesional, sin oferta laboral directa, demostrando beneficio sustancial al interés nacional."'::jsonb, 'published', 'json_seed'),
