  ('translation', 'sites.features', 'es', '["Diseño profesional y responsivo","Tienda online con carrito y WhatsApp","Panel de control para gestionar productos","Alojamiento gratuito en Vercel","Base de datos gratuita (Supabase)","Integración con redes sociales","Control de usuarios por roles","SEO básico incluido"]'::jsonb, 'published', 'json_seed'),
