  ('translation', 'sites.intro', 'en', '"We build modern, fast, and personalized websites for companies and professionals. With responsive layout, admin panel, WhatsApp integration and free hosting, you have everything to build your online presence."'::jsonb, 'published', 'json_seed'),
  ('translation', 'sites.intro', 'pt', '"Desenvolvemos sites modernos, rápidos e personalizados para empresas e profissionais. Com layout responsivo, painel administrativo, integração com WhatsApp e hospedagem gratuita, você tem tudo o que precisa para marcar presença na internet."'::jsonb, 'published', 'json_seed'),
  ('translation', 'sites.intro', 'es', '"Desarrollamos sitios modernos, rápidos y personalizados para empresas y profesionales. Con diseño responsivo, panel administrativo, integración con WhatsApp y alojamiento gratuito, tienes todo para tu presencia online."'::jsonb, 'published', 'json_seed'),
